// User preference detection
async function loadTheme(defaultTheme) {
  const userTheme = await getUserThemePreference();

  if (userTheme === 'dark') {
    const { DarkTheme } = await import('./themes/DarkTheme');
    return DarkTheme;
  }

  const { LightTheme } = await import('./themes/LightTheme');
  return LightTheme;
}

// Prefetch on hover
function LinkWithPrefetch({ to, children }) {
  const handleMouseEnter = () => {
    // Prefetch when user hovers over link
    import(`./routes/${to}.js`);
  };

  return (
    <a 
      href={to}
      onMouseEnter={handleMouseEnter}
      onClick={async (e) => {
        e.preventDefault();
        const module = await import(`./routes/${to}.js`);
        // Navigate to route
      }}
    >
      {children}
    </a>
  );
}

